import React, { createContext, useState, useContext, useEffect } from 'react';
import {
  loginUser,
  registerUser,
  logoutUser,
  getProfile,
  getGoogleAuthUrl,
} from '../services/api';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [token, setToken] = useState(localStorage.getItem('auth_token'));
  const [authLoading, setAuthLoading] = useState(true);
  const [currentProject, setCurrentProject] = useState(null);
  const [projects, setProjects] = useState([
    { id: '1', name: 'Senior Engineer - Q2', role: 'Senior Developer', department: 'Engineering', createdAt: '2026-05-01' },
    { id: '2', name: 'Product Lead - Q2', role: 'Product Manager', department: 'Product', createdAt: '2026-04-28' },
  ]);

  const persistToken = (newToken) => {
    localStorage.setItem('auth_token', newToken);
    setToken(newToken);
  };

  const clearAuth = () => {
    localStorage.removeItem('auth_token');
    setToken(null);
    setUser(null);
    setCurrentProject(null);
  };

  const bootstrapProfile = async (activeToken) => {
    const response = await getProfile(activeToken);
    const payload = response.data?.data || response.data;
    const profile = payload.profile || payload.data?.profile || payload;
    setUser(profile);
  };

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const urlToken = params.get('token');
    if (urlToken) {
      persistToken(urlToken);
      params.delete('token');
      params.delete('provider');
      const nextSearch = params.toString();
      const nextUrl = `${window.location.pathname}${nextSearch ? `?${nextSearch}` : ''}`;
      window.history.replaceState({}, document.title, nextUrl);
    }

    const activeToken = urlToken || localStorage.getItem('auth_token');
    if (!activeToken) {
      setAuthLoading(false);
      return;
    }

    bootstrapProfile(activeToken)
      .catch(() => {
        clearAuth();
      })
      .finally(() => setAuthLoading(false));
  }, []);

  const login = async (email, password) => {
    const response = await loginUser({ email, password });
    const payload = response.data?.data || response.data;
    if (!payload?.token) {
      throw new Error(payload?.message || 'Login failed');
    }
    persistToken(payload.token);
    setUser(payload.profile || { email });
    return payload;
  };

  const register = async (email, password, name) => {
    const response = await registerUser({ email, password, name });
    const payload = response.data?.data || response.data;
    if (!payload?.token) {
      throw new Error(payload?.message || 'Register failed');
    }
    persistToken(payload.token);
    setUser(payload.profile || { email, name });
    return payload;
  };

  const startGoogleAuth = () => {
    window.location.href = getGoogleAuthUrl();
  };

  const logout = async () => {
    if (token) {
      try {
        await logoutUser(token);
      } catch (error) {
        // Ignore API errors on logout
      }
    }
    clearAuth();
  };

  const createProject = (projectData) => {
    const newProject = {
      id: Date.now().toString(),
      ...projectData,
      createdAt: new Date().toISOString().split('T')[0],
    };
    setProjects([newProject, ...projects]);
    setCurrentProject(newProject);
    return newProject;
  };

  const selectProject = (projectId) => {
    const selected = projects.find((p) => p.id === projectId);
    setCurrentProject(selected);
  };

  const deleteProject = (projectId) => {
    setProjects(projects.filter((p) => p.id !== projectId));
    if (currentProject?.id === projectId) {
      setCurrentProject(null);
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        authLoading,
        currentProject,
        projects,
        login,
        register,
        startGoogleAuth,
        logout,
        createProject,
        selectProject,
        deleteProject,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within AuthProvider');
  }
  return context;
};
